<x-admin-layout title="مخزن المواد"><x-accounting-nav/><div class="admin-heading"><div><h1>مخزن المواد</h1><p>الرصيد يزيد بالمشتريات وينقص بالاستهلاك المسجل. الكلفة تعتمد متوسط قيمة المواد الموجودة.</p></div><a class="button primary" href="{{ route('accounting.entries') }}">إدخال شراء للمخزن</a></div><div class="accounting-columns"><section><form method="get" class="catalog-filters"><input name="q" value="{{ request('q') }}" placeholder="ابحث عن مادة" aria-label="البحث في المخزن"><button class="button secondary">بحث</button></form><div class="table-scroll"><table class="accounting-stock-table"><thead><tr><th>المادة</th><th>الرصيد</th><th>الوحدة</th><th>متوسط كلفة الوحدة</th><th>قيمة الرصيد</th><th>الإجراءات</th></tr></thead><tbody>@forelse($items as $row)@php $basis=$row->quantity_milli>0?$row->quantity_milli:$row->valuation_quantity_milli; $value=$row->quantity_milli>0?$row->value_milli_iqd:$row->valuation_value_milli_iqd; @endphp<tr data-stock-item="{{ $row->id }}"><td><b>{{ $row->name }}</b><small class="accounting-code" dir="ltr">{{ $row->code }}</small>@if(!$row->active)<span class="badge warn">موقوفة</span>@elseif($row->quantity_milli<=$row->minimum_milli)<span class="badge warn">رصيد منخفض</span>@endif</td><td>{{ $math::format($row->quantity_milli) }}</td><td>{{ \App\Models\StockItem::UNITS[$row->unit] }}</td><td>{{ $basis>0?$math::format($math::mulDiv($value,1000,$basis)).' د.ع':'لم تسجّل كلفة' }}</td><td>{{ $math::format($row->value_milli_iqd) }} د.ع</td><td><a class="text-link" href="{{ route('accounting.stock.item',$row) }}">فتح ←</a></td></tr>@empty<tr><td colspan="6">أضف أول مادة، ثم سجّل شراءها لإدخال الرصيد والكلفة.</td></tr>@endforelse</tbody></table></div>{{ $items->links() }}</section><section class="panel"><h2>{{ $item?'تعديل المادة':'إضافة مادة' }}</h2><form class="resource-form" method="post" action="{{ route('accounting.stock.save',['item'=>$item?->id]) }}" data-stock-form>@csrf<label>اسم المادة<input name="name" value="{{ old('name',$item?->name) }}" required maxlength="120"></label><label>رمز المادة<input name="code" value="{{ old('code',$item?->code) }}" required maxlength="60" dir="ltr"></label><label>الوحدة<select name="unit">@foreach(\App\Models\StockItem::UNITS as $key=>$label)<option value="{{ $key }}" @selected(old('unit',$item?->unit??'sheet')===$key)>{{ $label }}</option>@endforeach</select></label><div data-stock-dimensions class="device-form-row"><label>عرض الورقة / ملم<input name="width_mm" type="number" min="10" max="3000" step="0.01" value="{{ old('width_mm',$item?->width_mm??210) }}"></label><label>ارتفاع الورقة / ملم<input name="height_mm" type="number" min="10" max="3000" step="0.01" value="{{ old('height_mm',$item?->height_mm??297) }}"></label></div><label>تنبيه عند هذا الرصيد أو أقل<input name="minimum" type="number" min="0" max="1000000" step="0.001" value="{{ old('minimum',$math::format($item?->minimum_milli??0,false)) }}"></label><label class="checkbox-label"><input type="checkbox" name="active" value="1" @checked(old('active',$item?->active??true))>مادة فعالة</label><button class="button primary">حفظ المادة</button></form>@if($item)<form method="post" action="{{ route('accounting.stock.waste',$item) }}" class="resource-form accounting-void">@csrf<input type="hidden" name="request_id" value="{{ (string)\Illuminate\Support\Str::uuid() }}"><h3>تالف / استهلاك يدوي</h3><label>الكمية المراد خصمها<input name="quantity" type="number" min="0.001" step="0.001" max="{{ $math::format($item->quantity_milli,false) }}" required></label><label>السبب<input name="note" maxlength="500" minlength="3" required></label><button class="button secondary">تسجيل خصم من المخزن</button></form>@endif</section></div><section class="panel accounting-section"><h2>سجل حركات {{ $item?->name??'المخزن' }}</h2><div class="table-scroll"><table class="accounting-stock-table"><thead><tr><th># / التاريخ</th><th>المادة</th><th>الحركة</th><th>الكمية</th><th>القيمة / د.ع</th><th>الرصيد بعدها</th><th>البيان</th></tr></thead><tbody>@foreach($movements as $movement)<tr><td>#{{ $movement->id }}<small class="accounting-code">{{ $movement->created_at->format('Y/m/d H:i') }}</small></td><td>{{ $movement->item->name }}</td><td>{{ \App\Models\StockMovement::TYPES[$movement->type] }}</td><td dir="ltr">{{ $math::format($movement->quantity_milli) }}</td><td dir="ltr">{{ $math::format($movement->value_milli_iqd) }}</td><td>{{ $math::format($movement->balance_milli) }}</td><td>{{ $movement->note }}@if($movement->type==='waste')<form method="post" action="{{ route('accounting.stock.reverse',$movement) }}" class="accounting-reverse">@csrf<input name="reason" placeholder="سبب التصحيح" aria-label="سبب عكس حركة التالف" required minlength="3" maxlength="500"><button class="button secondary small">عكس</button></form>@endif</td></tr>@endforeach</tbody></table></div>{{ $movements->links() }}</section></x-admin-layout>
